188	        mvc.perform(post("/api/emergency-overrides").contentType(MediaType.APPLICATION_JSON)
189	                        .content(objectMapper.writeValueAsString(overrideBody(
190	                                "nf-3", ctx.key("nf3"), ctx.channel, ctx.prefix + "ghost",
191	                                ctx.newsGrant, 5, T_1020, T_1030))))
192	                .andExpect(status().isNotFound());
193	        createOverrideRaw("nf-4", ctx.key("nf4"), ctx.channel, ctx.newsAsset, 999999, 5,
194	                        T_1020, T_1030)
195	                .andExpect(status().isNotFound());
196	        getOverrideRaw(ctx.prefix + "ghost").andExpect(status().isNotFound());
197	        postJson("/api/emergency-overrides/" + ctx.prefix + "ghost/cancel",
198	                        Map.of("requestId", "nf-5"))
199	                .andExpect(status().isNotFound());
200	
201	        // 422：授权不属于该频道
202	        Ctx other = newContext();
203	        createOverrideRaw("nm-1", ctx.key("nm1"), ctx.channel, ctx.newsAsset,
204	                        other.newsGrant, 5, T_1020, T_1030)
205	                .andExpect(status().isUnprocessableEntity())
206	                .andExpect(jsonPath("$.error").value("GRANT_NOT_MATCHED"));
207	        // 422：授权素材不匹配（movie 的授权用于 news 素材）
208	        createOverrideRaw("nm-2", ctx.key("nm2"), ctx.channel, ctx.newsAsset,
209	                        ctx.movieGrant, 5, T_1020, T_1030)
210	                .andExpect(status().isUnprocessableEntity())
211	                .andExpect(jsonPath("$.error").value("GRANT_NOT_MATCHED"));
212	
213	        // 422：授权未完整覆盖区间（授权 10:00-10:20，插播 10:10-10:30）
214	        long shortGrant = createGrant(ctx.channel, ctx.newsAsset,
215	                "2026-09-22T10:00:00.000+08:00", "2026-09-22T10:20:00.000+08:00");
216	        createOverrideRaw("nc-1", ctx.key("nc1"), ctx.channel, ctx.newsAsset,
217	                        shortGrant, 5, "2026-09-22T10:10:00.000+08:00", T_1030)
218	                .andExpect(status().isUnprocessableEntity())
219	                .andExpect(jsonPath("$.error").value("GRANT_NOT_COVERING"));
220	
221	        // 422：保底素材不能用于插播（授权校验前即拒绝）
222	        createOverrideRaw("fb-1", ctx.key("fb1"), ctx.channel, ctx.fallbackAsset,
223	                        ctx.newsGrant, 5, T_1020, T_1030)
224	                .andExpect(status().isUnprocessableEntity())
225	                .andExpect(jsonPath("$.error").value("FALLBACK_ASSET_NOT_GRANTABLE"));
226	
227	        // 422：指定授权已撤销（撤销先提交）
228	        long revokedGrant = createGrant(ctx.channel, ctx.alertAsset, GRANT_FROM, GRANT_TO);
229	        postJson("/api/grants/" + revokedGrant + "/revoke", Map.of("requestId", "rv-g"))
230	                .andExpect(status().isOk());
231	        createOverrideRaw("rv-1", ctx.key("rv1"), ctx.channel, ctx.alertAsset,
232	                        revokedGrant, 5, T_1020, T_1030)
233	                .andExpect(status().isUnprocessableEntity())
234	                .andExpect(jsonPath("$.error").value("GRANT_INVALID"));
235	
236	        // 409：同频道同优先级 ACTIVE 区间重叠（端点相接之外的部分重叠）
237	        createOverrideRaw("ov-2", ctx.key("ov-2"), ctx.channel, ctx.alertAsset,
238	                        ctx.alertGrant, 5, T_1025, T_1035)
239	                .andExpect(status().isConflict())
240	                .andExpect(jsonPath("$.error").value("OVERRIDE_INTERVAL_CONFLICT"));
241	        // 与另一条不同优先级的区间重叠不受影响（已在上面验证 3 级可重叠；这里重叠已有 5 级 nf1）
242	        createOverrideRaw("ov-3", ctx.key("ov-3"), ctx.channel, ctx.alertAsset,
243	                        ctx.alertGrant, 9, T_1025, T_1035)
244	                .andExpect(status().isOk());
245	
246	        // 409：重复 overrideKey
247	        createOverrideRaw("dup-1", ctx.key("nf1"), ctx.channel, ctx.newsAsset,
248	                        ctx.newsGrant, 5, "2026-09-22T15:00:00.000+08:00",
249	                        "2026-09-22T15:10:00.000+08:00")
250	                .andExpect(status().isConflict())
251	                .andExpect(jsonPath("$.error").value("DUPLICATE_OVERRIDE_KEY"));
252	
253	        // 409：取消 ACTIVE 后再次取消
254	        postJson("/api/emergency-overrides/" + ctx.key("nf1") + "/cancel",
255	                        Map.of("requestId", "cancel-nf1"))
256	                .andExpect(status().isOk());
257	        postJson("/api/emergency-overrides/" + ctx.key("nf1") + "/cancel",
258	                        Map.of("requestId", "cancel-nf1-again"))
259	                .andExpect(status().isConflict())
260	                .andExpect(jsonPath("$.error").value("OVERRIDE_NOT_ACTIVE"));
261	    }
