 * 测试可替换为可控实现，避免依赖真实等待。
 */
public interface PlayoutClock {

    /** 当前时间，UTC 纪元毫秒。 */
    long nowMs();
}

package com.example.starter.playout;

import org.springframework.stereotype.Component;

/**
 * 系统时钟实现：生产环境默认使用。
 */
