    @Test
    void settleBeforeEndRejected() throws Exception {
        Ctx ctx = newContext();
        publishProgram(ctx);
        createLive(ctx, "req-c", "op", "lo-e", ctx.liveAsset, ctx.liveGrant, T_1000, T_1100)
                .andExpect(status().isOk());

        // 覆盖未结束：结算 409，响应给出剩余时长差额
        clock.set(T_1030);
