                .andExpect(status().isNotFound());
        // 404：授权不存在
        createLiveRaw("nf-3", "op", ctx.key("k3"), ctx.liveAsset, T_1000, T_1100,
                        List.of(channelEntry(ctx.channel, 999999)))
                .andExpect(status().isNotFound());
        // 404：明细 / 诊断 / 撤销 / 结算目标不存在
        getLive(ctx, "ghost").andExpect(status().isNotFound());
